  edges=[(i,j) for i in range(n) for j in range(i+1,n)]
  D=len(edges); cnt=[0]*(D+1)
  for mask in range(1<<D):
    m=mask.bit_count()
    if m<n-1: continue
    adj=[[] for _ in range(n)]
